"""Generate db/seed_taxonomy.sql from ml/data/taxonomy/taxonomy.json (so SQL and ML share ONE vocabulary).

python -m tapdix_ml.data.taxonomy_sql > db/seed_taxonomy.sql
"""

from __future__ import annotations

from .taxonomy import load_taxonomy


def q(s: str) -> str:
    return "'" + s.replace("'", "''") + "'"


def build() -> str:
    cats = load_taxonomy()["categories"]
    out = [
        "-- GENERATED by tapdix_ml.data.taxonomy_sql from ml/data/taxonomy/taxonomy.json - do not edit by hand.",
        "-- Idempotent. Run after db/migrations/002_ml_ready_fixes.sql.",
        "BEGIN;",
        "",
    ]
    rows = ",\n".join(
        f"    ({q(c['name_en'])}, {q(c['slug'])}, {q(c['name_az'])}, {q(c['name_ru'])}, {q(c['description_az'])})"
        for c in cats
    )
    out += [
        "INSERT INTO service_categories (category_name, slug, name_az, name_ru, description) VALUES",
        rows,
        "ON CONFLICT (category_name) DO UPDATE SET slug = EXCLUDED.slug, name_az = EXCLUDED.name_az, name_ru = EXCLUDED.name_ru,",
        "    description = COALESCE(service_categories.description, EXCLUDED.description), is_active = TRUE;",
        "",
    ]
    skills = ",\n".join(
        f"    ({q(c['slug'])}, {q(s['name_en'])}, {q(s['code'])}, {q(s['name_az'])})"
        for c in cats
        for s in c["skills"]
    )
    out += [
        "INSERT INTO skills (category_id, skill_name, skill_code, skill_name_az, description)",
        "SELECT c.category_id, v.name_en, v.code, v.name_az, v.name_az",
        "FROM service_categories c JOIN (VALUES",
        skills,
        ") AS v(cat_slug, name_en, code, name_az) ON c.slug = v.cat_slug",
        "ON CONFLICT (category_id, skill_name) DO UPDATE SET skill_code = EXCLUDED.skill_code, skill_name_az = EXCLUDED.skill_name_az,",
        "    description = COALESCE(skills.description, EXCLUDED.description), is_active = TRUE;",
        "",
    ]
    pts = ",\n".join(
        f"    ({q(c['slug'])}, {q(p['code'])}, {q(p['name_en'])}, {q(p['name_az'])}, "
        f"{'ARRAY[' + ', '.join(q(f) for f in p['risk_flags']) + ']::text[]' if p['risk_flags'] else chr(39) + '{}' + chr(39) + '::text[]'})"
        for c in cats
        for p in c["problem_types"]
    )
    out += [
        "INSERT INTO problem_types (category_id, code, name_en, name_az, risk_flags)",
        "SELECT c.category_id, v.code, v.name_en, v.name_az, v.risk_flags",
        "FROM service_categories c JOIN (VALUES",
        pts,
        ") AS v(cat_slug, code, name_en, name_az, risk_flags) ON c.slug = v.cat_slug",
        "ON CONFLICT (code) DO UPDATE SET name_en = EXCLUDED.name_en, name_az = EXCLUDED.name_az, risk_flags = EXCLUDED.risk_flags,",
        "    category_id = EXCLUDED.category_id, is_active = TRUE;",
        "",
    ]
    links = ",\n".join(
        f"    ({q(p['code'])}, {q(s)})"
        for c in cats
        for p in c["problem_types"]
        for s in p["skills"]
    )
    out += [
        "INSERT INTO problem_type_skills (problem_type_id, skill_id)",
        "SELECT pt.problem_type_id, s.skill_id FROM (VALUES",
        links,
        ") AS v(pt_code, skill_code)",
        "JOIN problem_types pt ON pt.code = v.pt_code JOIN skills s ON s.skill_code = v.skill_code",
        "ON CONFLICT DO NOTHING;",
        "",
        "COMMIT;",
        "",
    ]
    return "\n".join(out)


if __name__ == "__main__":
    print(build(), end="")
